const gameNavIcons={home:'<path d="m3 11 9-8 9 8M5 10v11h14V10M9 21v-7h6v7"/>',farms:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2Zm6-2v16m6-14v16"/>',market:'<path d="M3 9h18l-2-6H5Zm1 0v12h16V9M9 21v-7h6v7M3 9c0 4 5 4 5 0 0 4 8 4 8 0 0 4 5 4 5 0"/>',settings:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>'};
function gameIcon(key){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${gameNavIcons[key]}</svg>`}
function farmsPage(){return heading('Карта ферм','Выберите место, где будет расти ваш урожай.')+`<section class="farms-atlas" aria-label="Схема направлений Farm-off"><div class="atlas-caption">FARM-OFF · НАШИ НАПРАВЛЕНИЯ<small>Схема, не географическая карта</small></div><div class="atlas-road" aria-hidden="true"></div><div class="atlas-pins">${farmLocations.map((c,i)=>`<button class="atlas-pin pin-${i}" onclick="showFarmLocation('${c.id}')"><span class="atlas-marker">${i===0?'🌱':'⌖'}</span><strong>${c.name}</strong><small>${i===0?'Ферма доступна':'Скоро'}</small></button>`).join('')}</div><div class="atlas-trees" aria-hidden="true"><img src="art/tree.svg" alt=""><img src="art/tree.svg" alt=""><img src="art/house.svg" alt=""></div></section><section class="panel farm-directory"><h2>Фермы</h2>${farmLocations.map(c=>`<div class="event row"><div><b>${c.name}</b><small>${c.id==='krasnodar'?'Ферма на ул. Победы, 479':'Ферма пока не подключена'}</small></div><button class="btn ${c.id==='krasnodar'?'':'light'}" onclick="showFarmLocation('${c.id}')">Подробнее</button></div>`).join('')}<p class="note">Здесь представлены фермы сервиса. Личные грядки и данные других пользователей не показываются.</p></section>`}
function showFarmLocation(id){const city=farmLocations.find(c=>c.id===id);if(!city)return;const live=id==='krasnodar';modalForm(esc(city.name),live?`<img class="farm-detail-art" src="art/house.svg" alt="Иллюстрация фермы"><h3>Ферма в Белореченске</h3><p>Краснодарский край, Белореченск, ул. Победы, 479.</p><p>Открыта демоаренда. Подберите размер грядки и наблюдайте за своим хозяйством.</p><div class="object-options"><button type="button" class="btn" onclick="changeFarmCity('krasnodar')">В моё хозяйство здесь</button><button type="button" class="btn light" onclick="changeFarmCity('krasnodar');location.hash='choose-bed'">Выбрать грядку</button></div>`:`<p>В этом городе ферма пока не подключена. Аренда станет доступна после её открытия.</p><button type="button" class="btn light" onclick="modal.close()">Вернуться к карте</button>`,()=>{})}
const beforeGameNavRender=render;render=function(){beforeGameNavRender();const route=location.hash.slice(1)||'home';if(route==='farms'){$('#app').innerHTML=farmsPage();$('#crumb').textContent='КАРТА ФЕРМ'}let dock=document.getElementById('game-dock');if(!dock){dock=document.createElement('div');dock.id='game-dock';dock.setAttribute('role','navigation');dock.setAttribute('aria-label','Быстрые переходы');document.body.append(dock)}const active=route==='farms'?'farms':route==='market'?'market':['settings','wallet'].includes(route)?'settings':['home','rent','choose-bed'].includes(route)||route.startsWith('bed-')?'home':'';dock.innerHTML=[['home','Хозяйство'],['farms','Карта ферм'],['market','Маркет'],['settings','Профиль']].map(([key,label])=>`<a href="#${key}" ${key===active?'aria-current="page"':''}>${gameIcon(key)}<span>${label}</span></a>`).join('');document.body.classList.add('has-game-dock')};render();
